def google_site_rss(domain):
    """구글 뉴스에서 한 언론사 사이트의 최근 1일 사건사고 기사만 검색"""
    q = urllib.parse.quote(f"site:{domain} {SITE_QUERY_WORDS} when:1d")
    return f"https://news.google.com/rss/search?q={q}&hl=ko&gl=KR&ceid=KR:ko"

