def is_not_incident(title, content):
    """사건사고 '발생' 기사가 아닌 것(서평·광고·정책·발언·사설·기술·과학·역사·상품·예방)을 걸러냄"""
    if NON_NEWS_RE.search(title):
        return True
    text = title + " " + (content or "")
    if REVIEW_RE.search(title) or (REVIEW_RE.search(text) and re.search(r"지음|옮김|\d+쪽|출판사|펴냄", text)):
        return True
    if AD_RE.search(text):
        return True
    warn = WARNING_RE.search(title)
    hard = HARD_FACT_RE.search(title)
    if not STRICT_FACT_RE.search(title) and (STATS_RE.search(title) or ORG_EVENT_RE.search(title)):
        return True
    if not hard:
        # '결과'가 없는 기술 소개·과학·회고·상품 기사
        if SCIENCE_RE.search(title) or HISTORY_RE.search(title):
            return True
        if TECH_RE.search(title) and not re.search(r"조류|고병원성|구제역|방역|살처분|가금|농장|일당|피해자|피해액|총책|조직원|\d+\s*억|범행|덜미", title):
            return True
        if COMMERCE_RE.search(title) and not CRIME_HINT_RE.search(title):
            return True
        # 대비·예방·예정 (단, 주의보·경보 '발령'은 시민이 알아야 하므로 남김)
        if not warn and (STRONG_PREP_RE.search(title) or (PREP_RE.search(title) and not FACT2_RE.search(title))):
            return True
    fact = FACT2_RE.search(title)
    if not fact and not warn:
        if POLICY_RE.search(title):
            return True
        if SPEAKER_RE.search(title) and QUOTE_RE.search(title):
            return True                  # 누가 "…"라고 말했다는 기사
        if EDITORIAL_RE.search(title):
            return True
    elif SPEAKER_RE.search(title) and QUOTE_RE.search(title) and POLICY_RE.search(title):
        return True                      # 사건 낱말이 있어도 '○○의원 "…해야"' 꼴이면 발언 기사
    return False


