_KO_AFTER = (r"(?!\s*(?:국적|출신|대사관|국민|교민|관광객|유학생|노동자|근로자|선원|업체|기업|산\s))"
             r"(?=[^가-힣]|$|(?:에서|에선|에도|에는|서도|서는|에|서|의|은|는|이|가|도|를|을|과|와|로|측|군|내|령|주)(?:[^가-힣]|$))")
_HANJA_RX = {
    "美": r"美(?!친)(?!\s*(?:관광객|유학생|국적|대사관|동포|교포))", "中": r"(?:^|[\s…,·\"'“‘\[\(])中(?=[\s·,]|[가-힣]{2})(?!\s*(?:사망|숨|부상|사고|발견|체포|검거|적발|추락|폭발|화재|실종|붕괴|관광객|유학생|국적|대사관|동포|교포))",
    "日": r"(?<![0-9])日(?=[\s·,]|[가-힣])(?!\s*(?:관광객|유학생|국적|대사관))", "英": r"英(?=[\s·,]|[가-힣])", "露": r"露", "獨": r"獨", "佛": r"佛", "印": r"印(?=[\s·,])", "濠": r"濠", "臺": r"臺",
}


def _build_world():
    rows = []
    for label, la, ln, words in WORLD_PLACES:
        for w in words:
            amb = w.startswith("?")
            w = w.lstrip("?")
            if w in _HANJA_RX:
                rx = re.compile(_HANJA_RX[w])
            elif w == "이란":
                rx = re.compile(r"(?<![가-힣'’”\"\)\]])이란" + _KO_AFTER)
            elif re.match(r"^[A-Za-z .]+$", w):
                rx = re.compile(r"(?<![A-Za-z])" + re.escape(w), re.I)
            else:
                rx = re.compile(r"(?<![가-힣])" + r"\s*".join(re.escape(p) for p in w.split(" ")) + _KO_AFTER)
            rows.append((rx, label, la, ln, amb, w[:1]))
    return rows


_WORLD = _build_world()


def find_foreign(title, full=None):
    """제목에 나온 해외 지명 → (표시 이름, 위도, 경도). 없으면 None"""
    title = _FOREIGN_CLEAN.sub(" ", title)
    ctx = None
    for rx, label, la, ln, amb, probe in _WORLD:
        if probe not in title and not probe.isascii():
            continue
        if not rx.search(title):
            continue
        if amb:
            if ctx is None:
                ctx = bool(FOREIGN_CTX_RE.search(full or title))
            if not ctx:
                continue
        return label, la, ln
    return None


def overseas_sub(text):
    """해외 분쟁 기사의 소분류 (한글 제목 기준)"""
    if KO_PEACE_RE.search(text) and not KO_CASUALTY_RE.search(text):
        return "해외 휴전·협상·재건"
    if re.search(r"테러|폭탄|총격|암살|인질|자폭|괴한|피격|스파이|간첩|체포|구금|총기\s*난사", text):
        return "해외 테러·피격"
    return "해외 전쟁·분쟁"


# 국내 대분류 → 해외 소분류
def _overseas_from(group, sub):
    if group == NATURE_GROUP:
        return "해외 자연재해"
    if group in ("화재·사고", "교통사고"):
        return "해외 사고·재난"
    if sub == "테러·공중협박":
        return "해외 테러·피격"
    if group in ("감염병·보건", "실종·변사", "생활안전·소동"):
        return "해외 기타"
    return "해외 범죄"


# ── 해외 언론(영문 제목) ──
EN_PLACE_RE = re.compile(r"Ukrain|Russia|Kyiv|Moscow|Crimea|Kharkiv|Odesa|Donetsk|Israel|Gaza|Hamas|Hezbollah|Leban|Beirut|Iran|Tehran|Syria|Yemen|Houthi|Red Sea|Iraq|Sudan|Myanmar|Taiwan|South China Sea|North Korea|Pyongyang|Pakistan|Kashmir|Afghan|Taliban|Somalia|Sahel|Mali\b|Congo|Nigeria|Venezuela|Hormuz|Black Sea|West Bank|Jerusalem|NATO|Pentagon|military|army|navy|air force|troops|warship|fighter jet|militant|rebel|soldier", re.I)
EN_EVENT_RE = re.compile(r"scrambl(e|es|ed)|tanker (hit|attacked|struck|seized)|landmine|mine blast|artillery|howitzer|tank (fire|attack)|prisoner (swap|exchange)|POWs?\b|surrender(s|ed)?\b|raid(s|ed)?\b|spy (arrested|detained)|arrest(s|ed) .{0,30}(spy|spies|espionage)|detain(s|ed)|car bomb|suicide bomb|guided missile|air\s?strike|air raid|missile (strike|attack)|missiles? hit|drone (strike|attack)|strikes? (on|hit|kill)|struck|shell(ing|ed)|bomb(ing|ed|s)\b|blast|explosion|explode|kill(s|ed)\b|dead\b|death toll|wounded|attack(s|ed)?\b|shot down|shoots down|downed|intercept(s|ed)|sunk\b|sinks\b|sinking|torpedo|seiz(es|ed)|captur(es|ed)|hijack|invad(es|ed)|incursion|offensive|clash(es)?\b|fir(es|ed) (a |an )?(missile|rocket|ballistic)|launch(es|ed) (a |an )?(missile|rocket|attack|strike|ballistic)|rocket fire|gunmen|ambush|assassinat|coup\b|hostage", re.I)
EN_HARD_RE = re.compile(r"kill(s|ed)\b|dead\b|death toll|wounded|injur|sunk\b|sinks\b|shot down|downed|explosion|blast|struck|strikes? (hit|kill)|destroy|captur(es|ed)|seiz(es|ed)", re.I)
EN_TALK_RE = re.compile(r"\b(warns?|warning|threatens?|vows?|urges?|calls? for|talks|negotiat\w*|plans?|considers?|could|may|might|would|fears?|concerns?|analysis|opinion|explainer|what to know|what we know|why|how|interview|podcast|live updates?|briefing|review|timeline|in pictures|editorial|column|anniversary|history|remember\w*|look back)\b", re.I)


def classify_en(title):
    """해외 언론 영문 제목 → (소분류, 대분류). 실제 사건이 아니면 None."""
    if re.search(r"football|soccer|\bmatch\b|league|\bgoal\b|tournament|world cup|olympic|\bscore|film|movie|review|book|novel|game\b", title, re.I):
        return None                      # 스포츠·문화 기사
    # 휴전·평화 협상·재건: 분쟁 지역 기사이면 '해외 휴전·협상·재건'으로 올림 (경고·전망 기사여도 협상 국면은 중요한 소식)
    if EN_PEACE_RE.search(title) and EN_PLACE_RE.search(title) and not re.search(r"trade|tariff|wage|union|contract|budget|merger|deal with (?:apple|google|microsoft)", title, re.I):
        return "해외 휴전·협상·재건", OVERSEAS_GROUP
    if not (EN_EVENT_RE.search(title) and EN_PLACE_RE.search(title)):
        return None
    if EN_TALK_RE.search(title) and not EN_HARD_RE.search(title):
        return None                      # 경고·전망·분석·회고 등은 제외
    if re.search(r"North Korea|Pyongyang", title, re.I):
        return "북한 도발", "국가안보·테러"
    if re.search(r"gunmen|terror|suicide bomb|assassinat|shooting|hostage|ambush|car bomb", title, re.I):
        return "해외 테러·피격", OVERSEAS_GROUP
    return "해외 전쟁·분쟁", OVERSEAS_GROUP


def foreign_talk(title_ko):
    """번역한 해외 기사 제목이 '주장·경고·전망'일 뿐 실제 사건이 아니면 True"""
    if KO_PEACE_RE.search(title_ko):
        return False                     # 휴전·협상·재건 소식은 올림
    return bool(KO_TALK_RE.search(title_ko) and not KO_CASUALTY_RE.search(title_ko))


def _match_rules(t, full):
    """(소분류, 대분류, 넓은분류여부, 제목에서찾았는지) 또는 None"""
    for sub, group, rx, broad in RULES:          # 1차: 제목만
        if rx.search(t):
            return sub, group, broad, True
    if not TITLE_HINT_RE.search(t):              # 제목에 사건 낱말이 전혀 없으면 본문만으로는 인정하지 않음
        return None
    for sub, group, rx, broad in RULES:          # 2차: 제목+요약 (넓은 분류는 제외)
        if broad:
            continue
        if rx.search(full):
            return sub, group, broad, False
    return None


def _classify_incident(title, content, t, full):
    """국내·해외 공통: 사건사고 기사인지 판단하고 (소분류, 대분류)를 돌려줌"""
    if is_not_incident(title, content):
        return None
    found = _match_rules(t, full)
    if not found:
        return None
    sub, group, broad, in_title = found

    if sub == "구조·안전사고" and re.search(r"고양이|강아지|반려|동물|새끼", t):
        return None
    soft = group in SOFT_GROUPS or broad
    # 본문에서만 찾은 '비유로도 쓰이는' 분류는 제목에 실제 결과가 있어야 인정
    if not in_title and soft and not (FACT2_RE.search(t) or WARNING_RE.search(t)):
        return None
    # 경제 기사: '4천달러 붕괴', '주가 추락' 등
    if FINANCE_RE.search(t) and (soft or not (group in FINANCE_OK_GROUPS or sub in FINANCE_OK_SUBS)):
        return None
    # 드라마·예능·영화 줄거리 기사
    if ENT_STRONG_RE.search(t):
        return None
    ent = ENT_SPORT_RE.search(t) or ENT_SOURCE_RE.search(content or "")
    # 연예 기사: 연예인이 실제로 사고를 내거나(들이받아·추돌·숨져) 입건·구속된 경우,
    # 또는 영화제·시상식·공연장 '현장에서 실제 사건사고가 난' 경우(화재·폭발·압사·부상·대피·출동 등)만 통과
    real = LEGAL_FACT_RE.search(t) or HARD_FACT_RE.search(t) or EVENT_INCIDENT_RE.search(t)
    if ent and not real:
        return None
    if ent and soft and not (HARD_FACT_RE.search(t) or EVENT_INCIDENT_RE.search(t)):
        return None
    # 과거 논란·사건을 다시 꺼낸 기사(트라우마·재조명·회상 등)는 지금 일어난 사건이 아님
    if PAST_TALK_RE.search(t) and not STRICT_FACT_RE.search(t):
        return None
    # 스포츠 기사: 골 '폭발', 순위 '추락' 같은 표현 때문에 잘못 잡히는 것 방지 (선수가 실제로 입건·구속된 경우만 통과)
    if SPORTS_RE.search(t) and (soft or not LEGAL_FACT_RE.search(t)):
        return None
    if QUOTED_METAPHOR_RE.search(title) and soft and not HARD_FACT_RE.search(t):
        return None
    if broad and sub in ("기타 범죄", "경찰·소방 출동", "소동·해프닝", "혼잡·인파") and (POLITICS_RE.search(t) or FINANCE_RE.search(t)):
        return None
    if soft and (METAPHOR_RE.search(t) or POLITICS_RE.search(t)) and not INCIDENT_FACT_RE.search(t):
        return None
    # 폭발: 실제 폭발 사고의 정황(가스·공장·부상·대피 등)이 제목에 없으면 비유로 봄
    if sub == "폭발·가스누출" and "폭발" in t and not re.search(r"가스\s*누출|유독\s*가스|누출", t) and not EXPLOSION_CTX_RE.search(t):
        return None
    if sub == "붕괴·추락" and not COLLAPSE_CTX_RE.search(t):
        return None
    # 자연재해: 날씨 '예보'만 있는 기사는 제외 (피해가 났거나 주의보·경보가 발령된 경우만)
    if group == NATURE_GROUP:
        warn, dmg = WARNING_RE.search(t), DAMAGE_RE.search(t)
        quake = sub == "지진·화산" and re.search(r"규모\s*\d|발생|감지|흔들|분화|분출", t)
        if FORECAST_RE.search(t) and not warn and not dmg and not quake:
            return None
        if sub != "기상특보·경보" and warn and not dmg and re.search(r"발령|발효|격상|확대|해제", t):
            sub = "기상특보·경보"       # 피해 소식 없이 특보 발령만 전하는 기사
        elif sub == "기상특보·경보" and dmg:
            for s2, g2, rx2, b2 in RULES:   # 특보 속에 실제 피해가 난 기사는 재해 종류로 분류
                if g2 == NATURE_GROUP and s2 != "기상특보·경보" and rx2.search(t):
                    sub = s2
                    break
    if sub in ("소동·해프닝", "혼잡·인파") and not re.search(r"경찰|소방|119|112|출동|신고|구조|대피|부상|다쳐|통제|인파|몰려|마비", t):
        return None                      # 경찰·소방이 실제로 움직였거나 사람이 몰린 일만
    if sub == "경찰·소방 출동" and not re.search(r"출동|112|119|신고\s*(?:접수|받|로|에)|대치|구조|대피|부상|다쳐|다쳤|통제|수색|체포|검거|추격|사고(?!\s*(?:예방|대비|줄))|긴급", t):
        return None
    return sub, group


def classify(title, content):
    """(소분류, 대분류) 반환. 사건사고가 아니면 None."""
    if CAMPAIGN_RE.search(title) and not INCIDENT_FACT_RE.search(title) and not WARNING_RE.search(title):
        return None
    t = PRE_CLEAN.sub(" ", title)
    full = PRE_CLEAN.sub(" ", title + " " + (content or ""))
    if NON_NEWS_RE.search(title) or AD_RE.search(full):
        return None

    # ── 1) 북한 관련 국가안보 ──
    if NK_RE.search(t) and NK_EVENT_RE.search(t) and not re.search(r"북한과?\s*(?:관련\s*없|무관)|대공\s*혐의점\s*없", t):
        if HISTORY_RE.search(t) and not HARD_FACT_RE.search(t):
            return None
        if KO_TALK_RE.search(t) and not KO_CASUALTY_RE.search(t) and not re.search(r"발사|침투|침범|귀순|월북", t):
            return None
        if re.search(r"간첩", t):
            return "간첩·내란·외환", "국가안보·테러"
        return "북한 도발", "국가안보·테러"

    # ── 2) 해외에서 일어난 일인지 ──
    foreign = find_foreign(t, full)
    if foreign and foreign[0] == "북한":
        foreign = None
    if foreign and (DOMESTIC_CTX_RE.search(t) or _has_domestic_place(t)):
        foreign = None                   # 제목에 국내 지명이 함께 있으면 국내 사건 (예: '중국인 관광객 제주서…')
    if foreign:
        if SPORTS_RE.search(t) or REVIEW_RE.search(t) or ENT_STRONG_RE.search(t):
            return None
        if (HISTORY_RE.search(t) or SCIENCE_RE.search(t) or TECH_RE.search(t)) and not HARD_FACT_RE.search(t):
            return None
        # 휴전·평화 협상·재건 국면: 분쟁 지역 소식이면 올림
        if KO_PEACE_RE.search(t) and (FOREIGN_RE.search(t) or WAR_RE.search(t)) and not re.search(r"무역|관세|임금|노조|노사|예산|인수|합병", t):
            return overseas_sub(t), OVERSEAS_GROUP
        # 전쟁·분쟁: 실제 벌어진 일만 (경고·전망·분석은 제외)
        if WAR_RE.search(t) or (FOREIGN_RE.search(t) and CONFLICT_RE.search(t) and not re.search(r"교통사고|추돌|화재|지진|홍수|산불|태풍|폭우|붕괴", t)):
            if KO_TALK_RE.search(t) and not KO_CASUALTY_RE.search(t):
                return None
            return overseas_sub(t), OVERSEAS_GROUP
        res = _classify_incident(title, content, t, full)
        if not res:
            return None
        return _overseas_from(res[1], res[0]), OVERSEAS_GROUP

    # ── 3) 국내 사건사고 ──
    return _classify_incident(title, content, t, full)


def all_tags(title, sub, group):
    """제목에 함께 나온 다른 사건 유형까지 모두 돌려줌 (첫 번째 = 대표 분류).
    예) '차량 추돌 후 화재…' → ['화재', '교통사고']  → 화면에서 두 분류 모두 표시되고, 두 분류 필터에 모두 나옵니다."""
    tags = [sub]
    if group == OVERSEAS_GROUP or sub == "북한 도발":
        return tags
    t = PRE_CLEAN.sub(" ", title)
    for s, g, rx, broad in RULES:
        if broad or s in tags or g == OVERSEAS_GROUP:
            continue
        if not rx.search(t):
            continue
        # 분류할 때와 같은 '비유 표현' 거르기를 그대로 적용
        if s == "붕괴·추락" and not COLLAPSE_CTX_RE.search(t):
            continue
        if s == "폭발·가스누출" and "폭발" in t and not re.search(r"가스\s*누출|유독\s*가스|누출", t) and not EXPLOSION_CTX_RE.search(t):
            continue
        if g == NATURE_GROUP and group != NATURE_GROUP and not (WARNING_RE.search(t) or DAMAGE_RE.search(t)):
            continue
        if g == "감염병·보건" and (SPORTS_RE.search(t) or ENT_SPORT_RE.search(t)):
            continue
        tags.append(s)
        if len(tags) >= 4:
            break
    return tags


