def _rx(alias):
    body = r"\s*".join(re.escape(p) for p in alias.split(" "))
    return re.compile(r"(?<![가-힣])" + body + r"(?:(?![가-힣])|(?=[" + _SUFFIX_OK + r"]))")


@functools.lru_cache(maxsize=None)
def _dong_rx(label):
    """동 이름 찾기. '역삼동'으로 묶어 둔 동도 기사에 '역삼1동·역삼 2동·역삼제1동'처럼 번호가 붙어 있으면 찾음"""
    if len(label) >= 3 and label[-1] in "동가":
        stem, last = label[:-1], label[-1]
        return re.compile(r"(?<![가-힣])" + re.escape(stem) + r"\s?(?:제?\d{1,2}(?:[·.,]\d{1,2})?)?" + re.escape(last)
                          + r"(?:(?![가-힣])|(?=[" + _SUFFIX_OK + r"]))")
    return _rx(label)


class Region:
    def __init__(self, sido, name, lat, lng):
        self.sido, self.name, self.lat, self.lng = sido, name, lat, lng
        self.label = f"{sido} {name}"
        self.strong, self.weak = set(), set()
        self.dongs = None

    @property
    def radius(self):
        if self.name.endswith("구"):
            return 0.008
        if self.name.endswith("시"):
            return 0.02
        return 0.03


def build_regions():
    rows = []
    for sido, entries in SIGUNGU.items():
        for name, lat, lng in entries:
            r = Region(sido, name, lat, lng)
            parts = name.split(" ")
            if sido == "경기도" and name == "광주시":
                r.strong |= {"경기 광주", "경기도 광주", "경기 광주시", "경기도 광주시"}
            elif len(parts) == 2:                      # 예: 수원시 영통구
                city, gu = parts
                r.strong |= {name, gu, f"{city[:-1]} {gu}"}
            else:
                r.strong.add(name)
                stem = name[:-1]
                if name == "세종시":
                    r.strong.add("세종특별자치시")
                elif name.endswith("구") and len(stem) >= 2:
                    (r.strong if stem in _STANDALONE_GU else r.weak).add(stem)   # 그 외 줄임말은 시·도가 같이 있을 때만
                elif name.endswith("시") and stem not in SIDO_RX_NAMES:
                    (r.weak if stem in _NEED_SUFFIX else r.strong).add(stem)
                elif name.endswith("군"):
                    r.weak.add(stem)
            for sub, marks in LANDMARKS.items():
                if sub == r.label:
                    r.strong |= set(marks)
            r.inst = set()
            for table in (INSTITUTIONS, INSTITUTIONS_NATIONAL):
                for sub, marks in table.items():
                    if sub.strip() == r.label:
                        r.inst |= set(marks)
            d = DONG_DATA.get(r.label)
            if d:
                r.dongs = _dong_aliases(d)
            rows.append(r)
    # 같은 표현이 여러 지역에 있으면(예: 중구, 동구, 서구) 시·도가 함께 있어야만 인정
    count = {}
    for r in rows:
        for a in r.strong | r.weak:
            count[a] = count.get(a, 0) + 1
    for r in rows:
        r.compiled = []
        for a in r.strong:
            r.compiled.append((_rx(a), a, count[a] > 1, a.split(" ")[0]))
        for a in r.weak:
            r.compiled.append((_rx(a), a, True, a.split(" ")[0]))
        # 기관명은 글자 그대로 포함되어 있는지만 확인 (후순위)
        r.inst_compiled = [(re.compile(a), a) for a in r.inst]
    return rows


SIDO_RX_NAMES = {"서울", "부산", "대구", "인천", "광주", "대전", "울산", "세종", "제주"}


def _dong_aliases(csv):
    out = []
    seen = set()
    for d in csv.split(","):
        d = d.strip()
        if not d or d == "전체" or "가동" in d:
            continue
        m = re.match(r"^([가-힣]+?)(\d|제)", d)
        label = (m.group(1) + d[-1]) if m else d
        if len(label) < 3 or label in seen:
            continue
        seen.add(label)
        out.append(label)
    return out


_REGIONS = None


def regions():
    global _REGIONS
    if _REGIONS is None:
        _REGIONS = build_regions()
    return _REGIONS


def find_sidos(text):
    t = re.sub(r"경기도?\s*광주", "경기 ", text)       # '경기 광주'가 광주광역시로 오해되지 않도록
    return {s: m.start() for s, rx in SIDO_RX.items() for m in [rx.search(t)] if m}


def match_sigungu(text, hint_sido):
    text = _NOT_PLACE.sub(" ", text)
    sidos = set(find_sidos(text))
    if hint_sido:
        sidos.add(hint_sido)
    best = None
    for r in regions():
        for rx, alias, need_sido, probe in r.compiled:
            if probe not in text:                      # 빠른 사전 검사 (속도 향상)
                continue
            if need_sido and r.sido not in sidos:
                continue
            m = rx.search(text)
            if not m:
                continue
            key = (0, m.start(), -len(alias))
            if best is None or key < best[0]:
                best = (key, r)
        for rx, alias in r.inst_compiled:              # 법원·검찰·부처·공공기관 등 기관 소재지 (후순위)
            m = rx.search(text)
            if not m:
                continue
            key = (1, m.start(), -len(m.group()))
            if best is None or key < best[0]:
                best = (key, r, m.group())
    if not best:
        return None
    r = best[1]
    label = r.label
    dong = None
    if not r.dongs and " " not in r.name:
        # '안산 고잔동'처럼 구(區)를 빼고 쓴 경우: 그 시에 속한 구들의 동 이름에서 찾음
        for c in regions():
            if c.sido == r.sido and c.name.startswith(r.name + " ") and c.dongs:
                hit = next((d for d in c.dongs if d[:2] in text and _dong_rx(d).search(text)), None)
                if hit:
                    r, label = c, c.label
                    break
    if r.dongs:
        dbest = None
        for dlabel in r.dongs:
            if dlabel[:2] not in text:
                continue
            m = _dong_rx(dlabel).search(text)
            if m and (dbest is None or m.start() < dbest[0]):
                exact = re.sub(r"\s+", "", m.group(0))
                dbest = (m.start(), exact if re.search(r"\d", exact) else dlabel)   # '역삼1동'처럼 번호까지 있으면 그대로 (지도에 더 정확히)
        if dbest:
            dong = dbest[1]
            label += " " + dong
    inst_alias = best[2] if len(best) > 2 else None
    return label, r.lat, r.lng, r.radius, inst_alias, r.label, dong


def _jitter(key, radius):
    h = hashlib.md5(key.encode("utf-8")).digest()
    return (h[0] / 255 - 0.5) * 2 * radius, (h[1] / 255 - 0.5) * 2 * radius


def _has_domestic_place(text):
    """제목에 국내 지명(시·도 또는 시·군·구)이 있는지"""
    return bool(find_sidos(text)) or match_sigungu(text, None) is not None


# ── 기사에 적힌 '구체적인 장소'(요금소·역·터널·아파트 등) 찾기 ──
#   예) "고잔요금소 인근에서…" → 고잔요금소.  찾은 장소는 아래 지오코딩으로 실제 좌표를 구해 지도에 그 지점을 찍습니다.
_POI_SUFFIX = (r"(?:요금소|톨게이트|나들목|분기점|휴게소|터널|대교|교차로|사거리|오거리|삼거리|네거리|지하차도|고가도로|고가차도|지하상가|터미널|공항|부두|선착장|"
               r"해수욕장|해변|공원|시장|백화점|아울렛|아파트|오피스텔|초등학교|초교|중학교|고등학교|대학교|병원|의료원|산업단지|산단|공단|물류센터|발전소|제철소|저수지|"
               r"휴양림|스키장|골프장|경기장|체육관|캠핑장|주유소|지구대|파출소|유원지|수목원|방파제|등대|국립공원|IC|JC|JCT|TG|"
               # 더 작은 범위의 장소 (건물·생활시설)
               r"빌딩|빌라|상가|타워|센터|호텔|모텔|여관|교회|성당|사찰|도서관|주민센터|행정복지센터|경찰서|소방서|우체국|마트|편의점|PC방|노래방|노래연습장|찜질방|사우나|목욕탕|"
               r"어린이집|유치원|요양원|요양병원|초등|광장|운동장|놀이터|주차장|정류장|버스정류장|환승센터|육교|지하보도|횡단보도|공영주차장|아이파크|자이|푸르지오|래미안|힐스테이트|e편한세상)")
# 도로명 주소 (예: '중앙로 123', '테헤란로 45길 6')  → 건물 단위로 가장 정확한 위치
_ROAD_RX = re.compile(r"(?<![가-힣0-9])([가-힣0-9]{1,10}(?:대로|로|길)(?:\s*\d{1,3}(?:번?길))?\s*\d{1,4}(?:-\d{1,4})?)(?=[^0-9가-힣]|$|(?:에서|의|번지|일대|인근|앞|소재|에)(?:[^가-힣]|$))")
_ROAD_STOP = re.compile(r"^(?:경로|진로|항로|활로|통로|선로|해로|수로|도로|차로|철로|대로|하로|무로|육로|노로|위로|기로|미로|회로|전로|퇴로|귀로|오로지|그길|이길|저길|한길|외길|지름길|오솔길|산길|들길|물길|뱃길|하늘길|빗길|눈길|밤길|귀갓길|출근길|퇴근길|등굣길|하굣길)")
# 읍·면 아래 마을 '리' (예: '화도읍 묵현리', '양서면 용담리')
_RI_RX = re.compile(r"(?<![가-힣])([가-힣]{1,4}(?:읍|면))\s*([가-힣]{1,4}리)(?![가-힣])")
_POI_END = r"(?=[^가-힣]|$|(?:에서|에선|에도|에|서|의|은|는|이|가|도|를|을|과|와|로|으로|앞|옆|안|내|쪽|행)(?:[^가-힣]|$))"
_POI_RX = re.compile(r"(?<![가-힣A-Za-z0-9])([가-힣A-Za-z0-9]{2,12}?" + _POI_SUFFIX + r")" + _POI_END)
_POI_SINGLE_RX = re.compile(r"(?<![가-힣])([가-힣]{2,6}(?:역|항|산|천|교|봉|댐|섬))(?=\s*(?:에서|인근|부근|앞|근처|방향|방면|일대|주변|입구|정상|승강장|선로|해상|앞바다))")
_POI_STRONG_RX = re.compile(r"(?:요금소|톨게이트|나들목|분기점|휴게소|터널|대교|공항|IC|JC|JCT|TG|역|항|댐)$")
_POI_STOP_RX = re.compile(r"^(?:주식|부동산|금융|증권|외환|노동|중고|취업|채용|분양|전세|매매|도매|소매|온라인|글로벌|세계|국내|해외|대형|종합|요양|정신|동물|산부인과|한방|치과|어린이|"
                          r"해당|인근|같은|이웃|일반|고층|신축|임대|민간|공공|국립|시립|도립|사립|특수|전국|지역|공립|일부|여러|모든|전문|상급|응급|공동|고급|대단지|재건축|재개발|"
                          r"주상복합|노후|신도시|원룸|다세대|사고|화재|피해|근처|현장|해안|도심|시내|시외|고속|광역|마을|농어촌|자동차|반도체|화학|식품|제조|가구|섬유|공사|철거|건설|"
                          r"수산|농산물|재래|전통|야|벼룩|수입|수출|주택|상가|대학|국제|군|민자|원자력|화력|수력|태양광|풍력|버스|고속버스|시외버스|여객|화물|복합|"
                          r"서울|부산|대구|인천|광주|대전|울산|세종|경기|강원|충북|충남|전북|전남|경북|경남|제주|한국|우리|이번|지난|올해|내년|오늘|어제)")
_NOT_POI = {"부산", "울산", "마산", "군산", "서산", "아산", "익산", "안산", "오산", "양산", "경산", "논산", "금산", "괴산", "예산", "일산", "인천", "과천", "부천", "포천", "이천", "영천",
            "김천", "순천", "제천", "춘천", "홍천", "화천", "연천", "서천", "합천", "사천", "옥천", "진천", "예천", "북한산", "생산", "재산", "예산", "국산", "수산", "출산", "해산", "등산",
            "파산", "정산", "계산", "확산", "분산", "양산", "유산", "자산", "수입산", "중국산", "미국산", "하천", "개천", "온천", "실천", "추천", "공천", "기본", "종교", "학교", "외교",
            "비교", "절교", "포교", "선교", "불교", "유교", "육교", "철교", "대교", "공항", "어항", "저항", "사항", "조항", "문항", "반항", "출항", "입항", "결항", "운항", "취항", "회항",
            "지하철역", "기차역", "전철역", "통역", "번역", "지역", "구역", "광역", "영역", "현역", "용역", "방역", "면역", "징역", "악역", "주역", "조역", "무역", "전역", "예비역"}


def find_poi(text):
    """기사에서 구체적인 장소 이름 하나를 찾아 돌려줌 (없으면 None). 작은 범위(주소·건물)부터 찾음"""
    for m in _ROAD_RX.finditer(text):                 # 1) 도로명 주소
        name = re.sub(r"\s+", " ", m.group(1)).strip()
        road = re.match(r"[가-힣0-9]+(?:대로|로|길)", name)
        if road and not _ROAD_STOP.match(road.group(0)) and len(road.group(0)) >= 3:
            return name
    for m in _RI_RX.finditer(text):                   # 2) 읍·면 아래 마을(리)
        if m.group(2) not in ("관리", "처리", "거리", "우리", "무리", "요리", "자리", "소리", "마리", "머리", "논리", "진리", "수리", "정리", "유리", "의리", "비리", "총리"):
            return m.group(1) + " " + m.group(2)
    for m in _POI_RX.finditer(text):                  # 3) 건물·시설 이름
        name = m.group(1)
        stem = re.sub(_POI_SUFFIX + r"$", "", name)
        if len(stem) < 2 or _POI_STOP_RX.match(stem) or stem.isdigit():
            continue
        return name
    for m in _POI_SINGLE_RX.finditer(text):
        name = m.group(1)
        if name in _NOT_POI or (not name.endswith("역") and _POI_STOP_RX.match(name[:-1])):
            continue
        return name
    return None


def dist_km(a, b):
    dy, dx = (a[0] - b[0]) * 111.0, (a[1] - b[1]) * 88.0
    return (dy * dy + dx * dx) ** 0.5


def nearest_region(lat, lng):
    best = None
    for r in regions():
        d = dist_km((lat, lng), (r.lat, r.lng))
        if best is None or d < best[0]:
            best = (d, r)
    return best


# ── 지오코딩: 동(洞)·장소 이름 → 실제 좌표 ──
#   OpenStreetMap 의 무료 검색(Nominatim)을 씁니다. 1초에 1번만 요청할 수 있어서, 한 번 찾은 결과는 geocache.json 에 저장해 두고 다시 묻지 않습니다.
GEOCACHE_JSON = "geocache.json"
MAX_GEOCODE_PER_RUN = 40      # 한 번 실행(약 6분마다)에 새로 물어볼 최대 건수 (Nominatim 이용 규칙: 1초에 1번 이하)
GEO_UA = "woori-dongne-incident-map/1.0 (github actions news scraper)"
_geo = {"cache": None, "used": 0, "dirty": False, "fail": 0}


def geo_cache():
    if _geo["cache"] is None:
        try:
            with open(GEOCACHE_JSON, encoding="utf-8") as f:
                _geo["cache"] = json.load(f)
        except Exception:
            _geo["cache"] = {}
    return _geo["cache"]


def geo_save():
    if _geo["dirty"]:
        with open(GEOCACHE_JSON, "w", encoding="utf-8") as f:
            json.dump(_geo["cache"], f, ensure_ascii=False, sort_keys=True, indent=0)


def geocode(query, near=None, max_km=None, allow_net=True):
    """query → (위도, 경도). near 에서 max_km 보다 멀면 엉뚱한 곳으로 보고 버림."""
    cache = geo_cache()
    if query in cache:
        v = cache[query]
    else:
        if not allow_net or _geo["used"] >= MAX_GEOCODE_PER_RUN or _geo["fail"] >= 3:
            return None
        _geo["used"] += 1
        try:
            url = ("https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=kr&accept-language=ko&q="
                   + urllib.parse.quote(query))
            req = urllib.request.Request(url, headers={"User-Agent": GEO_UA})
            with urllib.request.urlopen(req, timeout=10) as r:
                data = json.loads(r.read().decode("utf-8", "ignore"))
            v = [round(float(data[0]["lat"]), 5), round(float(data[0]["lon"]), 5)] if data else None
        except Exception:
            _geo["fail"] += 1          # 서버가 응답하지 않으면 이번 실행에서는 그만 물어봄 (다음 실행 때 다시 시도)
            time.sleep(1.1)
            return None
        time.sleep(1.1)
        cache[query] = v
        _geo["dirty"] = True
    if not v:
        return None
    if near and max_km and dist_km(v, near) > max_km:
        return None
    return v[0], v[1]


def refine_locations(items, started=None):
    """동·장소 이름이 확인된 기사는 그 지점의 실제 좌표로 바꿈. (prec: poi=장소, dong=읍면동, sgg=시군구, sido=시도)"""
    n_poi = n_dong = 0
    for it in sorted(items, key=lambda x: -x["timestamp"]):
        g = it.pop("_geo", None)
        if not g:
            continue
        allow = started is None or time.time() - started < 600
        center, sgg, sido, place, dong = g.get("center"), g.get("sgg"), g.get("sido"), g.get("place"), g.get("dong")
        hit = None
        if place:
            if sgg or sido:
                hit = geocode(f"{sgg or sido} {place}", center, 30 if sgg else 150, allow)
            elif _POI_STRONG_RX.search(place):
                hit = geocode(place, None, None, allow)      # 지역 표기가 없어도 '○○요금소'처럼 분명한 장소는 찾아봄
                if hit:
                    near = nearest_region(hit[0], hit[1])
                    if near and near[0] < 40:
                        it["location"] = near[1].label
                    else:
                        hit = None
            if hit:
                dy, dx = _jitter(it["title"], 0.0004)
                it["lat"], it["lng"], it["prec"], it["place"] = round(hit[0] + dy, 5), round(hit[1] + dx, 5), "poi", place
                if place not in it["location"]:
                    it["location"] += " " + place
                n_poi += 1
        if not hit and dong and sgg:
            hit = geocode(f"{sgg} {dong}", center, 30, allow)
            if hit:
                dy, dx = _jitter(it["title"], 0.002)
                it["lat"], it["lng"], it["prec"] = round(hit[0] + dy, 5), round(hit[1] + dx, 5), "dong"
                n_dong += 1
    geo_save()
    return n_poi, n_dong


def locate(title, content, hint_sido=None, overseas=False):
    """(위치이름, 위도, 경도, 정밀도정보) 반환. 모르면 (미상, None, None, …)"""
    key = title
    full = title + " | " + (content or "")[:900]     # 요약 + 본문에서 찾은 위치 문장(loctext)까지
    if overseas:
        hit = find_foreign(title, full) or find_foreign(full, full)
        if hit:
            label, la, ln = hit
            dy, dx = _jitter(key, 0.25)
            name = "북한·접경지역" if label == "북한" else f"해외 ({label})"
            return name, round(la + dy, 4), round(ln + dx, 4), {"prec": "world"}
        return "해외 (위치 미상)", None, None, {"prec": None}
    place = find_poi(_NOT_PLACE.sub(" ", full))
    for scope in (title, full):
        res = match_sigungu(scope, hint_sido)
        if res:
            label, lat, lng, rad, inst_alias, sgg, dong = res
            if inst_alias:
                # 기관명으로만 찾은 경우: 기사에 다른 시·도가 따로 적혀 있으면 그쪽을 우선
                other = find_sidos(scope.replace(inst_alias, " "))
                if other:
                    sido = min(other, key=other.get)
                    la, ln = SIDO_CENTER[sido]
                    dy, dx = _jitter(key, 0.10)
                    return sido, round(la + dy, 4), round(ln + dx, 4), {"prec": "sido", "sido": sido, "center": (la, ln), "place": place}
                place = None             # 기관 소재지로 찍은 경우에는 장소 추정을 하지 않음
            dy, dx = _jitter(key, rad)
            return label, round(lat + dy, 4), round(lng + dx, 4), {"prec": "sgg", "sgg": sgg, "dong": dong, "center": (lat, lng), "place": place}
    for scope in (title, full):
        s = find_sidos(scope)
        if s:
            sido = min(s, key=s.get)
            la, ln = SIDO_CENTER[sido]
            dy, dx = _jitter(key, 0.10)
            return sido, round(la + dy, 4), round(ln + dx, 4), {"prec": "sido", "sido": sido, "center": (la, ln), "place": place}
    if hint_sido:
        la, ln = SIDO_CENTER[hint_sido]
        dy, dx = _jitter(key, 0.10)
        return hint_sido, round(la + dy, 4), round(ln + dx, 4), {"prec": "sido", "sido": hint_sido, "center": (la, ln), "place": place}
    return "대한민국 (세부 위치 미상)", None, None, {"prec": None, "place": place}


# ───────────────────────────────────────────────────────────────
# 4. 수집 보조 함수
# ───────────────────────────────────────────────────────────────
class _HTMLFilter(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, d):
        self.parts.append(d)


def clean_text(s):
    if not s:
        return ""
    f = _HTMLFilter()
    try:
        f.feed(s)
        s = "".join(f.parts)
    except Exception:
        pass
    return re.sub(r"\s+", " ", s).strip()


# ── 기사 본문에서 위치 문장 찾기 ──
#   RSS·구글 뉴스에는 제목(과 짧은 요약)만 있어서 '○○1동', '○○리', '○○로 12', '○○아파트' 같은 자세한 위치를 놓치기 쉽습니다.
#   그래서 위치가 시·군·구 이하로 확인되지 않은 최신 기사는 언론사 기사 페이지를 한 번 열어 본문에서 위치가 나오는 문장만 골라 둡니다(loctext).
MAX_ENRICH_PER_RUN = 30
_LOC_CUE_RE = re.compile(r"[가-힣]{1,6}\d{0,2}(?:가)?\d?동(?![가-힣])|[가-힣]{1,5}(?:읍|면)\s*[가-힣]{1,4}리(?![가-힣])|[가-힣]{1,5}(?:읍|면)(?![가-힣])|"
                         r"[가-힣0-9]{2,10}(?:대로|로|길)\s*\d|사거리|교차로|삼거리|오거리|[가-힣]{2,6}역(?![가-힣])|아파트|빌라|오피스텔|상가|IC|나들목|요금소|톨게이트|터널|휴게소|"
                         r"초등학교|중학교|고등학교|공원|시장|해수욕장|항구|부두|인근|일대|앞\s*도로|소재|번지")


class _BodyParser(HTMLParser):
    """기사 페이지에서 본문 문단(<p>, 기사 영역)과 요약(og:description)만 뽑음"""
    def __init__(self):
        super().__init__()
        self.parts, self.desc, self._skip, self._p = [], "", 0, 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("script", "style", "noscript", "header", "footer", "nav", "aside", "form", "button"):
            self._skip += 1
        elif tag == "meta" and (a.get("property") in ("og:description",) or a.get("name") == "description") and not self.desc:
            self.desc = a.get("content") or ""
        elif tag in ("p", "article") or (tag == "div" and re.search(r"article|content|news_?body|text|view", (a.get("id") or "") + " " + (a.get("class") or ""), re.I)):
            self._p += 1

    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript", "header", "footer", "nav", "aside", "form", "button"):
            self._skip = max(0, self._skip - 1)
        elif tag in ("p", "article", "div") and self._p:
            self._p -= 1

    def handle_data(self, d):
        if not self._skip and self._p and d.strip():
            self.parts.append(d)


def fetch_article_text(url):
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "text/html,*/*"})
    with urllib.request.urlopen(req, timeout=8) as r:
        raw = r.read(800_000)
        ctype = r.headers.get("Content-Type", "")
    m = re.search(r"charset=([\w-]+)", ctype, re.I) or re.search(rb"charset=[\"']?([\w-]+)", raw[:4000], re.I)
    enc = (m.group(1).decode() if isinstance(m.group(1), bytes) else m.group(1)) if m else "utf-8"
    try:
        html = raw.decode(enc, "ignore")
    except LookupError:
        html = raw.decode("utf-8", "ignore")
    p = _BodyParser()
    try:
        p.feed(html)
    except Exception:
        pass
    body = re.sub(r"\s+", " ", " ".join(p.parts))
    return (p.desc + " " + body).strip()


def location_sentences(text, limit=220):
    """본문에서 위치가 나오는 문장만 골라 짧게 (저작권을 고려해 위치 확인용 최소한만 보관)"""
    out, total = [], 0
    for s in re.split(r"(?<=[다요\.!?])\s+", text):
        s = s.strip()
        if 8 <= len(s) <= 220 and _LOC_CUE_RE.search(s) and s not in out:
            out.append(s)
            total += len(s)
            if total >= limit or len(out) >= 3:
                break
    return " ".join(out)[:limit]


_PREC_RANK = {"poi": 4, "dong": 3, "sgg": 2, "sido": 1, "world": 1, None: 0}


def enrich_locations(items, started):
    """위치가 자세하지 않은 최신 국내 기사: 기사 본문을 읽어 더 작은 범위의 위치를 찾음"""
    from concurrent.futures import ThreadPoolExecutor
    cands = []
    for v in sorted(items, key=lambda x: -x["timestamp"]):
        if len(cands) >= MAX_ENRICH_PER_RUN:
            break
        g = v.get("_geo") or {}
        if v.get("enr") or v.get("group") == OVERSEAS_GROUP or v.get("category") == "북한 도발":
            continue
        if not v.get("link") or v["link"].startswith("https://news.google.com"):
            continue
        if v.get("prec") in ("poi",) or g.get("place") or g.get("dong"):
            continue                                # 이미 장소·동까지 알고 있음
        cands.append(v)
    if not cands or time.time() - started > 420:
        return 0

    def one(v):
        try:
            return v, fetch_article_text(v["link"])
        except Exception:
            return v, ""
    with ThreadPoolExecutor(max_workers=8) as ex:
        res = list(ex.map(one, cands))
    better = 0
    for v, text in res:
        v["enr"] = 1                                # 한 번 확인한 기사는 다시 열지 않음
        lt = location_sentences(text) if text else ""
        if not lt:
            continue
        v["loctext"] = lt
        loc, lat, lng, geo = locate(v["title"], (v.get("content") or "") + " " + lt, v.get("hint"), False)
        old_g = v.get("_geo") or {}
        new_rank = _PREC_RANK.get(geo.get("prec"), 0) + (0.5 if (geo.get("place") or geo.get("dong")) else 0)
        old_rank = _PREC_RANK.get(v.get("prec"), 0) + (0.5 if (old_g.get("place") or old_g.get("dong")) else 0)
        if lat is not None and new_rank > old_rank:
            v["location"], v["lat"], v["lng"], v["prec"], v["_geo"] = loc, lat, lng, geo.get("prec"), geo
            better += 1
    return better


def split_publisher(title):
    """'기사 제목 - 언론사' → ('기사 제목', '언론사')"""
    m = re.match(r"^(.*\S)\s+[-–|]\s+([^-–|]{2,20})$", title)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    return title, None


def norm_key(title):
    return re.sub(r"[^0-9A-Za-z가-힣]", "", title)[:60]


def make_id(key):
    return int(hashlib.md5(key.encode("utf-8")).hexdigest()[:12], 16)


WEEKDAYS_KR = ["월요일", "화요일", "수요일", "목요일", "금요일", "토요일", "일요일"]


def fmt_time(ts):
    dt = datetime.fromtimestamp(ts, KST)
    return f"{dt.strftime('%Y.%m.%d')} ({WEEKDAYS_KR[dt.weekday()]}) {dt.strftime('%H:%M')}"


def fetch_entries(url):
    last = None
    for _ in range(2):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": UA, "Accept": "application/rss+xml, application/xml, text/xml, */*"})
            with urllib.request.urlopen(req, timeout=12) as r:
                data = r.read()
            return feedparser.parse(data).entries
        except Exception as e:      # noqa
            last = e
            time.sleep(1.5)
    raise last


def entry_timestamp(entry):
    for k in ("published_parsed", "updated_parsed"):
        v = entry.get(k)
        if v:
            try:
                return float(calendar.timegm(v))
            except Exception:
                pass
    return None


def build_item(entry, feed, now_ts):
    title_raw = clean_text(entry.get("title", ""))
    if not title_raw:
        return None
    link = entry.get("link", "") or ""
    ts = entry_timestamp(entry)
    if ts is None:
        ts = now_ts
    ts = min(ts, now_ts)

    source = feed["name"]
    title = title_raw
    if feed["kind"] == "google":
        title, pub = split_publisher(title_raw)
        src = entry.get("source")
        if isinstance(src, dict) and src.get("title"):
            pub = clean_text(src.get("title"))
            if title_raw.endswith(" - " + pub):
                title = title_raw[: -len(" - " + pub)].strip()
        if pub:
            source = pub
        content = title
    else:
        content = clean_text(entry.get("summary") or entry.get("description") or "") or title
    content = content[:400]

    cls = classify(title, content)
    if not cls:
        return None
    sub, group = cls
    return make_item(title, content, sub, group, source, link, ts, feed.get("hint"))


def make_item(title, content, sub, group, source, link, ts, hint, orig=None, loctext=None):
    overseas = group == OVERSEAS_GROUP or sub == "북한 도발"
    loc, lat, lng, geo = locate(title, content + (" " + orig if orig else "") + (" " + loctext if loctext else ""), None if overseas else hint, overseas)
    summary = content[:130] + ("..." if len(content) > 130 else "")
    return {
        "id": make_id(norm_key(title)),
        "title": title,
        "summary": summary,
        "content": content,
        "category": sub,
        "group": group,
        "tags": all_tags(title, sub, group),   # 함께 해당하는 분류들 (예: 화재 + 교통사고)
        "location": loc,
        "lat": lat,
        "lng": lng,
        "time": fmt_time(ts),
        "source": source,
        "link": link,
        "timestamp": ts,
        "hint": hint,
        "orig": orig,       # 해외 언론 기사의 원문(영문) 제목
        "embed": None,      # 이 사이트 안에 원문을 띄울 수 있는지 (False 면 언론사가 막아 둔 것)
        "prec": geo.get("prec"),   # 위치 정밀도: poi(장소) / dong(읍·면·동) / sgg(시·군·구) / sido(시·도) / world(해외) / None(모름)
        "place": None,      # 기사에 나온 구체적인 장소 이름 (좌표를 찾은 경우에만)
        "_geo": geo,        # 좌표를 더 정밀하게 찾기 위한 임시 정보 (저장 전에 지움)
    }


# ── 언론사가 '다른 사이트 안에서 보기'를 막아 뒀는지 확인 ──
#   막아 둔 언론사(예: "연결을 거부했습니다")는 화면 가운데에 빈 창 대신 안내와 원문 열기 버튼을 보여 줍니다.
MAX_EMBED_CHECK = 25       # 한 번 실행에 새로 확인할 언론사(도메인) 수


def domain_of(url):
    try:
        return urllib.parse.urlparse(url).netloc.lower()
    except Exception:
        return ""


def check_embeddable(url):
    """True: 띄울 수 있음 / False: 막혀 있음 / None: 확인 실패"""
    try:
        req = urllib.request.Request(url.replace("http://", "https://", 1), headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=8) as r:
            xfo = (r.headers.get("X-Frame-Options") or "").lower()
            csp = (r.headers.get("Content-Security-Policy") or "").lower()
        if "deny" in xfo or "sameorigin" in xfo:
            return False
        m = re.search(r"frame-ancestors([^;]*)", csp)
        if m and "*" not in m.group(1).split():
            return False
        return True
    except Exception as e:
        # https 로 열 수 없는 사이트는 https 페이지(GitHub Pages) 안에 띄울 수 없음
        return False if url.startswith("http://") else None


# ── 구글 뉴스 링크를 실제 언론사 기사 주소로 바꾸기 (실패해도 괜찮습니다) ──
def _b64_legacy(art_id):
    try:
        b = base64.urlsafe_b64decode(art_id + "=" * (-len(art_id) % 4)).decode("latin1")
        if b.startswith("\x08\x13\x22"):
            b = b[3:]
        if b.endswith("\xd2\x01\x00"):
            b = b[:-3]
        ba = bytearray(b, "latin1")
        n = ba[0]
        s = b[2:n + 1] if n >= 0x80 else b[1:n + 1]
        return s if s.startswith("http") else None
    except Exception:
        return None


def resolve_google_link(link):
    m = re.search(r"/articles/([^/?]+)", link)
    if not m:
        return None
    art_id = m.group(1)
    url = _b64_legacy(art_id)
    if url:
        return url
    try:
        req = urllib.request.Request(f"https://news.google.com/rss/articles/{art_id}", headers={"User-Agent": UA})
        html = urllib.request.urlopen(req, timeout=10).read().decode("utf-8", "ignore")
        sg = re.search(r'data-n-a-sg="([^"]+)"', html)
        ts = re.search(r'data-n-a-ts="([^"]+)"', html)
        if not (sg and ts):
            return None
        inner = ('["garturlreq",[["X","X",["X","X"],null,null,1,1,"US:en",null,1,null,null,null,null,null,0,1],'
                 '"X","X",1,[1,1,1],1,1,null,0,0,null,0],"%s",%s,"%s"]' % (art_id, ts.group(1), sg.group(1)))
        payload = "f.req=" + urllib.parse.quote(json.dumps([[["Fbv4je", inner]]]))
        req = urllib.request.Request(
            "https://news.google.com/_/DotsSplashUi/data/batchexecute", data=payload.encode("utf-8"),
            headers={"Content-Type": "application/x-www-form-urlencoded;charset=UTF-8", "User-Agent": UA})
        text = urllib.request.urlopen(req, timeout=10).read().decode("utf-8", "ignore")
        data = json.loads(text.split("\n\n")[1])
        real = json.loads(data[0][2])[1]
        return real if isinstance(real, str) and real.startswith("http") else None
    except Exception:
        return None


# ───────────────────────────────────────────────────────────────
# 4-2. 같은 사건을 다룬 기사 묶기
#   한 사건을 여러 언론사가 보도하면 기사 수만큼 건수가 늘어나므로,
#   같은 사건으로 보이는 기사에 같은 사건번호(event)를 붙입니다. 화면에서는 1건으로 세고 관련 기사를 함께 보여 줍니다.
# ───────────────────────────────────────────────────────────────
_EVENT_STOP = set("경찰 검찰 혐의 구속 구속영장 영장 청구 신청 입건 체포 검거 송치 기소 수사 조사 남성 여성 종합 속보 단독 사건 사고 발생 "
                  "피해 피해자 피의자 관련 오늘 어제 결국 당시 현장 확인 추정 가운데 이후 위해 대해 징역 선고 재판 법원".split())
_EVENT_STRONG = {"살인", "방화·실화", "약취·유인·인신매매", "체포·감금"}       # 같은 지역·같은 종류면 거의 같은 사건인 분류


# 사건 종류를 나타내는 흔한 낱말: 이것만 같다고 같은 사건은 아니므로 비슷함 계산에서 뺌
_EVENT_TYPE_RX = re.compile(r"개인정보|정보\s*유출|유출|해킹|화재|폭행|사기|보이스피싱|전세사기|투자사기|마약|음주운전|교통사고|절도|강도|성폭행|성추행|실종|추락|붕괴|폭발|공습|미사일|드론|공격|스토킹|협박|횡령|배임|침수|정전|산불|뺑소니|무면허|불법|의혹")


def _ev_tokens(title):
    title = _EVENT_TYPE_RX.sub(" ", title)
    return {w for w in re.findall(r"[가-힣A-Za-z0-9]{2,}", title) if w not in _EVENT_STOP and not w.isdigit()}


def _ev_bigrams(title):
    s = re.sub(r"[^가-힣0-9A-Za-z]", "", _EVENT_TYPE_RX.sub(" ", title))
    return {s[i:i + 2] for i in range(len(s) - 1)}


def _ev_sim(a, b):
    j = len(a["_bg"] & b["_bg"]) / max(1, len(a["_bg"] | b["_bg"]))
    shared = len(a["_tk"] & b["_tk"])
    overlap = shared / max(1, min(len(a["_tk"]), len(b["_tk"])))
    return j, shared, overlap


def assign_events(items):
    n = len(items)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    for it in items:
        it["_tk"] = _ev_tokens(it["title"])
        it["_bg"] = _ev_bigrams(it["title"])
        loc = it.get("location") or ""
        it["_loc"] = loc if (it.get("lat") is not None and " " in loc and not loc.startswith("해외")) else ""

    by_sub = {}
    for i, it in enumerate(items):
        by_sub.setdefault(it["category"], []).append(i)

    for sub, idxs in by_sub.items():
        # 1) 위치가 같은 기사끼리 / 위치를 모르는 기사끼리
        for a_pos in range(len(idxs)):
            a = items[idxs[a_pos]]
            for b_pos in range(a_pos + 1, len(idxs)):
                b = items[idxs[b_pos]]
                gap = abs(a["timestamp"] - b["timestamp"])
                if a["_loc"] != b["_loc"]:
                    continue
                j, shared, overlap = _ev_sim(a, b)
                if a["_loc"]:
                    same = gap <= 96 * 3600 and (j >= 0.2 or (shared >= 2 and j >= 0.12) or (sub in _EVENT_STRONG and gap <= 96 * 3600))
                else:
                    same = gap <= 48 * 3600 and (j >= 0.33 or (shared >= 3 and overlap >= 0.5))
                if same:
                    union(idxs[a_pos], idxs[b_pos])
        # 2) 위치를 모르는 기사가 위치를 아는 기사와 내용이 비슷하면 같은 사건으로 묶고 위치도 물려받음
        located = [i for i in idxs if items[i]["_loc"]]
        for i in idxs:
            a = items[i]
            if a["_loc"] or a["group"] == OVERSEAS_GROUP:
                continue
            best = None
            for k in located:
                b = items[k]
                if abs(a["timestamp"] - b["timestamp"]) > 72 * 3600:
                    continue
                j, shared, overlap = _ev_sim(a, b)
                if j >= 0.3 or (shared >= 3 and overlap >= 0.5):
                    if best is None or j > best[0]:
                        best = (j, k)
            if best:
                b = items[best[1]]
                union(best[1], i)
                dy, dx = _jitter(a["title"], 0.008)
                a["location"], a["lat"], a["lng"] = b["location"], round(b["lat"] + dy, 4), round(b["lng"] + dx, 4)
                a["prec"], a["place"] = b.get("prec"), b.get("place")

    # 3) 분류·위치가 달라도 제목이 거의 같은 기사(통신사 기사를 여러 언론사가 그대로 실은 것)는 같은 사건
    index = {}
    for i, it in enumerate(items):
        for w in it["_tk"]:
            if len(w) >= 3:
                index.setdefault(w, []).append(i)
    for i, a in enumerate(items):
        cand = {}
        for w in a["_tk"]:
            lst = index.get(w, ())
            if len(w) < 3 or len(lst) > 60:
                continue
            for k in lst:
                if k > i:
                    cand[k] = cand.get(k, 0) + 1
        for k, shared in cand.items():
            if shared < 2:
                continue
            b = items[k]
            if abs(a["timestamp"] - b["timestamp"]) > 48 * 3600:
                continue
            j, sh, overlap = _ev_sim(a, b)
            if j >= 0.45 or (sh >= 4 and overlap >= 0.7):
                union(i, k)

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    for members in groups.values():
        first = min(members, key=lambda k: items[k]["timestamp"])
        ev = make_id(norm_key(items[first]["title"]))
        for k in members:
            items[k]["event"] = ev
            items[k]["event_n"] = len(members)
    for it in items:
        for key in ("_tk", "_bg", "_loc"):
            it.pop(key, None)
    return len(groups)


# ───────────────────────────────────────────────────────────────
# 5. 저장/불러오기 및 실행
# ───────────────────────────────────────────────────────────────
def load_existing():
    if not os.path.exists(NEWS_JSON):
        return []
    try:
        with open(NEWS_JSON, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception as e:
        print(f"[경고] 기존 news.json 을 읽지 못했습니다: {e}")
        return []


def reprocess_existing(old):
    """기존 기사를 최신 분류/위치 규칙으로 다시 계산 (규칙을 고치면 과거 기사에도 적용됨)"""
    out = {}
    for it in old:
        try:
            title = it.get("title", "")
            source = it.get("source", "")
            if source.startswith("구글 뉴스"):
                t2, pub = split_publisher(title)
                if pub:
                    title, source = t2, pub
            if it.get("source") == "시민 직접 제보":
                continue
            content = it.get("content") or title
            ts = float(it.get("timestamp") or 0)
            if not ts:
                continue
            orig = it.get("orig")
            if orig:                                   # 해외 언론 번역 기사
                cls_en = classify_en(orig)
                if not cls_en or foreign_talk(title):
                    continue
                out[norm_key(title)] = make_item(title, title, cls_en[0], cls_en[1], source, it.get("link", ""), ts, None, orig)
                out[norm_key(title)]["embed"] = it.get("embed")
                continue
            cls = classify(title, content)
            if not cls:
                continue
            item = make_item(title, content[:400], cls[0], cls[1], source, it.get("link", ""), ts, it.get("hint"), None, it.get("loctext"))
            item["embed"] = it.get("embed")
            if it.get("enr"):
                item["enr"] = 1                        # 본문 위치 확인을 이미 한 기사
            if it.get("loctext"):
                item["loctext"] = it["loctext"]
            out[norm_key(title)] = item
        except Exception:
            continue
    return out


def main():
    now = datetime.now(KST)
    now_ts = now.timestamp()
    cutoff_ts = (now - timedelta(days=KEEP_DAYS)).timestamp()
    print("=== 우리동네 사건사고 수집 시작 ===", now.strftime("%Y-%m-%d %H:%M:%S"))

    items = reprocess_existing(load_existing())
    print(f"기존 기사 {len(items)}건 불러옴")

    new_count = 0
    ok_feeds = fail_feeds = 0
    started = time.time()
    do_google = google_due()
    feeds = build_feed_list(include_google=do_google)
    print(f"수집 주소 {len(feeds)}곳 (구글 뉴스 검색 {'포함' if do_google else '이번엔 건너뜀 · ' + str(GOOGLE_EVERY_SEC // 60) + '분마다 한 번'})")
    # 언론사 직접 RSS 는 여러 곳을 동시에, 구글 뉴스는 막히지 않도록 적게 동시에 내려받음
    press = [f for f in feeds if f["kind"] == "press"]
    goog = [f for f in feeds if f["kind"] != "press"]
    fetched = fetch_many(press, 16) + fetch_many(goog, 4)
    if do_google:
        mark_google_done()
    print(f"내려받기 완료: {time.time() - started:.1f}초")
    for feed, entries, err in fetched:
        label = f"{feed['name']}" + (f" [{feed['hint']}]" if feed["hint"] else "") + f" {feed['url'][:70]}"
        if err is not None or entries is None:
            fail_feeds += 1
            print(f"[실패] {label} → {type(err).__name__}: {str(err)[:80]}")
            continue
        got = 0
        for entry in entries[:300]:
            try:
                it = build_item(entry, feed, now_ts)
            except Exception:
                it = None
            if not it or it["timestamp"] < cutoff_ts:
                continue
            key = norm_key(it["title"])
            old = items.get(key)
            if old is None:
                items[key] = it
                new_count += 1
                got += 1
            else:
                # 같은 기사면, 구글 링크보다 언론사 직접 링크를 우선
                if old["link"].startswith("https://news.google.com") and not it["link"].startswith("https://news.google.com"):
                    old["link"] = it["link"]
        ok_feeds += 1
        print(f"[OK ] {label} → 전체 {len(entries)}건 중 신규 사건사고 {got}건")

    # ── 해외 언론: 실제 발생한 분쟁·공격 기사만 골라 한글로 번역 ──
    known_orig = {norm_key(v["orig"]) for v in items.values() if v.get("orig")}
    foreign = [{"name": n, "url": u, "google": False} for n, u in FOREIGN_FEEDS]
    if do_google:
        foreign += [{"name": "해외 언론", "url": google_rss_en(q), "google": True} for q in FOREIGN_QUERIES]
    foreign_fetched = fetch_many([f for f in foreign if not f["google"]], 10) + fetch_many([f for f in foreign if f["google"]], 3)
    translated = 0
    for feed, entries, err in foreign_fetched:
        if time.time() - started > 480:
            print("[주의] 수집 시간이 길어져 남은 해외 주소는 다음 실행으로 넘깁니다.")
            break
        label = f"{feed['name']} {feed['url'][:70]}"
        if err is not None or entries is None:
            fail_feeds += 1
            print(f"[실패] {label} → {type(err).__name__}: {str(err)[:80]}")
            continue
        ok_feeds += 1
        got = 0
        for entry in entries[:60]:
            if translated >= MAX_TRANSLATE_PER_RUN:
                break
            try:
                title_en = clean_text(entry.get("title", ""))
                source = feed["name"]
                if feed["google"]:
                    title_en, pub = split_publisher(title_en)
                    source = pub or source
                if not title_en or norm_key(title_en) in known_orig:
                    continue
                cls_en = classify_en(title_en)
                if not cls_en:
                    continue
                ts = min(entry_timestamp(entry) or now_ts, now_ts)
                if ts < cutoff_ts:
                    continue
                title_ko = translate_ko(title_en)
                translated += 1
                time.sleep(0.3)
                if not title_ko:
                    continue                       # 번역 실패 → 다음 실행 때 다시 시도
                known_orig.add(norm_key(title_en))
                if foreign_talk(title_ko):
                    continue                       # 주장·경고·전망 기사는 올리지 않음
                it = make_item(title_ko, title_ko, cls_en[0], cls_en[1], source, entry.get("link", "") or "", ts, None, title_en)
                key = norm_key(title_ko)
                if key not in items:
                    items[key] = it
                    new_count += 1
                    got += 1
            except Exception:
                continue
        print(f"[OK ] {label} → 전체 {len(entries)}건 중 신규 해외 사건 {got}건")
        time.sleep(0.3)
    print(f"해외 기사 번역 시도: {translated}건")

    # 구글 뉴스 링크 → 원문 주소 (최신 기사부터 일부만)
    resolved = 0
    pending = sorted([v for v in items.values() if v["link"].startswith("https://news.google.com")],
                     key=lambda x: -x["timestamp"])
    for v in pending[:MAX_RESOLVE_PER_RUN]:
        real = resolve_google_link(v["link"])
        if real:
            v["link"] = real
            resolved += 1
        time.sleep(0.4)
    print(f"원문 주소로 변환: {resolved}건 (구글 링크 남은 건수: {len(pending) - resolved}건)")

    # 언론사별로 '사이트 안에 띄우기'가 되는지 확인 (한 번 확인한 언론사는 다시 확인하지 않음)
    dom_embed = {}
    for v in items.values():
        if v.get("embed") is not None and not v["link"].startswith("https://news.google.com"):
            dom_embed.setdefault(domain_of(v["link"]), v["embed"])
    checked = 0
    for v in sorted(items.values(), key=lambda x: -x["timestamp"]):
        if not v["link"] or v["link"].startswith("https://news.google.com"):
            v["embed"] = None
            continue
        d = domain_of(v["link"])
        if d not in dom_embed and checked < MAX_EMBED_CHECK and time.time() - started < 540:
            dom_embed[d] = check_embeddable(v["link"])
            checked += 1
        v["embed"] = dom_embed.get(d)
    blocked = sorted(d for d, ok in dom_embed.items() if ok is False)
    print(f"화면 안 표시 확인: 새로 {checked}곳 확인 / 막아 둔 언론사 {len(blocked)}곳 {blocked[:12]}")

    final = [v for v in items.values() if v["timestamp"] >= cutoff_ts]
    final.sort(key=lambda x: -x["timestamp"])
    final = final[:MAX_ITEMS]
    n_enr = enrich_locations(final, started)            # 본문에서 '○○1동·○○리·○○로 12·○○아파트' 같은 자세한 위치 찾기
    print(f"기사 본문에서 더 자세한 위치를 찾은 기사: {n_enr}건")
    for v in final:
        v["id"] = make_id(norm_key(v["title"]))
    n_poi, n_dong = refine_locations(final, started)   # 동·장소 단위까지 좌표를 정밀하게
    for v in items.values():
        v.pop("_geo", None)
    n_events = assign_events(final)        # 같은 사건 기사 묶기

    with open(NEWS_JSON, "w", encoding="utf-8") as f:
        f.write("[\n" + ",\n".join(json.dumps(v, ensure_ascii=False) for v in final) + "\n]\n")

    by_day = {}
    by_src = {}
    for v in final:
        d = datetime.fromtimestamp(v["timestamp"], KST).strftime("%m-%d")
        by_day[d] = by_day.get(d, 0) + 1
        by_src[v["source"]] = by_src.get(v["source"], 0) + 1
    unknown = sum(1 for v in final if v["lat"] is None)
    print(f"같은 사건 묶기: 기사 {len(final)}개 → 사건 {n_events}건")
    print(f"=== 완료: 저장 {len(final)}건 (이번 신규 {new_count}건) / RSS 성공 {ok_feeds} 실패 {fail_feeds} ===")
    print("날짜별:", dict(sorted(by_day.items())))
    print("언론사 상위:", dict(sorted(by_src.items(), key=lambda x: -x[1])[:15]))
    print(f"위치 미상: {unknown}건 / 장소 단위 {n_poi}건 · 읍면동 단위 {n_dong}건 (이번 실행 지오코딩 요청 {_geo['used']}건)")
    by_group = {}
    for v in final:
        by_group[v["group"]] = by_group.get(v["group"], 0) + 1
    print("분류별:", dict(sorted(by_group.items(), key=lambda x: -x[1])))


if __name__ == "__main__":
    main()
